// Paginate returns a page of legacy_widgets with total count for offset-based pagination.
// A nil filter paginates all legacy_widgets.
func (c *legacyWidgetClient) Paginate(ctx context.Context, input PaginateInput[LegacyWidgetFilter], opts ...func(*CallOptions[LegacyWidgetFieldOptions])) (*PaginateResult[LegacyWidget], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableLegacyWidgets, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[LegacyWidgetFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate legacy_widgets count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		legacyWidgets, err := c.GetMany(ctx, &GetLegacyWidgetsInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate legacy_widgets: %w", err)
		}

		return &PaginateResult[LegacyWidget]{
			Items:      legacyWidgets,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[LegacyWidget]), nil
}

// Connection returns a Relay-style cursor-paginated connection of legacy_widgets.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *legacyWidgetClient) Connection(ctx context.Context, input ConnectionInput[LegacyWidgetFilter], opts ...func(*CallOptions[LegacyWidgetFieldOptions])) (*Connection[LegacyWidget], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		return nil, fmt.Errorf("connection legacy_widgets: LockMode is unsupported on sqlite dialect")
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableLegacyWidgets, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[LegacyWidgetFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection legacy_widgets count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		legacyWidgets, err := c.GetMany(ctx, &GetLegacyWidgetsInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection legacy_widgets: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(legacyWidgets) > limit
		if hasMore {
			legacyWidgets = legacyWidgets[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(legacyWidgets)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[LegacyWidget], len(legacyWidgets))
		for i, row := range legacyWidgets {
			cursor, err := encodeLegacyWidgetCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[LegacyWidget]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[LegacyWidget]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[LegacyWidget]), nil
}

// encodeLegacyWidgetCursor encodes cursor key values as a base64 JSON string.
func encodeLegacyWidgetCursor(keys []string, l *LegacyWidget) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = l.ID
		case "org_id":
			out["org_id"] = l.OrgID
		case "label":
			out["label"] = l.Label
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode legacy_widget cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// StreamLegacyWidgetsInput holds query parameters for streaming legacy_widgets records.
// Stream is iterator-style and intentionally has no Limit/Offset.
// Field selection is controlled via CallOptions.FieldOptions, not this struct.
type StreamLegacyWidgetsInput struct {
	Filter *LegacyWidgetFilter `json:"filter"`
	Sorts  []sql.Sort          `json:"sorts"`
}

// StreamLegacyWidgetFieldOptions controls scalar column selection for legacy_widgets streams.
// Stream cannot load relationships — only scalar columns are selectable.
type StreamLegacyWidgetFieldOptions struct {
	ID    bool `json:"id"`
	OrgID bool `json:"org_id"`
	Label bool `json:"label"`
}

// Columns returns the SQL column names for all selected columns, sorted alphabetically
