// scanPostTags scans rows into PostTag entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanPostTags(rows database.Rows, columns []string) ([]*PostTag, error) {
	var result []*PostTag
	for rows.Next() {
		p := &PostTag{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "post_id":
				targets[idx] = &p.PostID
			case "tag_id":
				targets[idx] = &p.TagID
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan post_tag: %w", err)
		}

		result = append(result, p)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate post_tag rows: %w", err)
	}
	return result, nil
}

